// commonMain — one ViewModel, bound by both platforms
data class CounterUi(val count: Int = 0, val isLoading: Boolean = false)

class CounterViewModel(private val repo: CounterRepo) : ViewModel() {
  private val _state = MutableStateFlow(CounterUi())
  val state: StateFlow<CounterUi> = _state.asStateFlow()

  fun increment() = viewModelScope.launch {
    _state.update { it.copy(isLoading = true) }
    _state.value = CounterUi(count = repo.increment())
  }
}

// imports: androidx.lifecycle.ViewModel, androidx.lifecycle.viewModelScope,
//   kotlinx.coroutines.flow.{MutableStateFlow, StateFlow, asStateFlow, update},
//   kotlinx.coroutines.launch — all resolve in commonMain via the multiplatform
//   lifecycle-viewmodel artifacts.

// Android / Compose Multiplatform — bind directly
@Composable
fun CounterScreen(vm: CounterViewModel = viewModel()) {
  val state by vm.state.collectAsStateWithLifecycle()
  Button(onClick = vm::increment) { Text("\${state.count}") }
}

